import { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, Color, DoubleSide } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, color, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'collection-card-1';

  const inner = new Group();
  root.add(inner);

  // ---- dimensions (matches atlas aspect 512x320 -> 1.6) ----
  const cardW = 2.4;
  const cardH = 1.5;

  // ---- depth plane 1: engineered gradient backing (frame) ----
  const backingGeo = new PlaneGeometry(cardW + 0.14, cardH + 0.14);
  const backingMat = new MeshStandardNodeMaterial({
    roughness: 0.65,
    metalness: 0.2,
    side: DoubleSide,
  });
  const gradientNode = mix(
    color(new Color(colors.surface)),
    color(new Color(colors.ink)),
    uv().y
  );
  backingMat.colorNode = gradientNode;
  const backing = new Mesh(backingGeo, backingMat);
  backing.position.z = -0.05;
  inner.add(backing);

  // ---- depth plane 2: hero image plane ----
  const imgGeo = new PlaneGeometry(cardW, cardH);
  const imgMat = new MeshStandardNodeMaterial({
    color: 0xffffff,
    roughness: 0.6,
    metalness: 0.25,
  });
  const imgMesh = new Mesh(imgGeo, imgMat);
  inner.add(imgMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // ---- depth plane 3: accent rule (foreground, <=10% of frame) ----
  const accentGeo = new BoxGeometry(cardW * 0.28, 0.045, 0.045);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.5,
    metalness: 0.4,
    clearcoat: 0.15,
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(-cardW * 0.36 + (cardW * 0.14), -cardH / 2 - 0.14, 0.03);
  inner.add(accentBar);

  // ---- subtle grain overlay ----
  const grainGeo = new PlaneGeometry(cardW, cardH);
  const grainMat = new MeshBasicNodeMaterial({ transparent: true });
  const grainUv = uv();
  const grainNoise = fract(
    sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  grainMat.colorNode = vec3(grainNoise, grainNoise, grainNoise);
  grainMat.opacityNode = grainNoise.mul(0.045);
  const grainMesh = new Mesh(grainGeo, grainMat);
  grainMesh.position.z = 0.02;
  inner.add(grainMesh);

  // ---- node-local rim light (accent hue), stays under global intensity caps ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.55);
  rimLight.position.set(-1.5, 0.8, 1.2);
  inner.add(rimLight);

  // ---- weighted-settle entrance (no linear easing, translate <=0.4) ----
  inner.position.y = -0.35;
  inner.scale.setScalar(0.97);
  [backingMat, imgMat, accentMat, grainMat].forEach((m) => {
    m.transparent = true;
    m.opacity = 0;
  });

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(
    [backingMat, imgMat, accentMat, grainMat],
    { opacity: 1, duration: 0.6, ease: 'power2.out' },
    0.05
  );
  tl.to(
    inner.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' },
    0
  );
  tl.to(
    inner.scale,
    { x: 1, y: 1, z: 1, duration: 0.55, ease: 'power4.out' },
    0.35
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    backingGeo.dispose();
    backingMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    grainGeo.dispose();
    grainMat.dispose();
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }
    inner.remove(rimLight);
    root.clear();
  };

  return root;
}
